#include <iostream>
using namespace std;
int main(){int r1,c1,r2,c2,a[10][10],b[10][10],z[10][10]={};cout<<"First rows/cols: ";cin>>r1>>c1;cout<<"Second rows/cols: ";cin>>r2>>c2;if(r1<1||r1>10||c1<1||c1>10||r2<1||r2>10||c2<1||c2>10||c1!=r2){cout<<"Invalid dimensions\n";return 0;}cout<<"First matrix: ";for(int i=0;i<r1;i++)for(int j=0;j<c1;j++)cin>>a[i][j];cout<<"Second matrix: ";for(int i=0;i<r2;i++)for(int j=0;j<c2;j++)cin>>b[i][j];for(int i=0;i<r1;i++)for(int j=0;j<c2;j++)for(int k=0;k<c1;k++)z[i][j]+=a[i][k]*b[k][j];for(int i=0;i<r1;i++){for(int j=0;j<c2;j++)cout<<z[i][j]<<" ";cout<<endl;}}
